    "aliases": [
      "小桃红"
    ],
    "meaning": "春意",
    "season": "春",
    "blurb": "花似梅花叶如榆，粉霞满枝。",
    "morph": "落叶灌木，花单瓣或重瓣，粉红色，叶形似榆。",
    "culture": "象征春意，北方春日重要花灌木。",
    "care": "原产中国北方，喜光耐寒，耐旱怕涝。",
    "story": "榆叶梅叶似榆、花如梅，是北方早春最热闹的灌木花，北京胡同的春天常由它点亮。老舍笔下北平的春日常有\"榆叶梅开\"的闲笔；国徽设计时期正值其花期，设计师们常于玉兰、榆叶梅旁推敲草图。它花期虽短却开得轰轰烈烈，花语为春回大地、坚韧不拔。",
    "image": "images/prunus-triloba.webp",
