    "culture": "象征纯洁，是庭院基础花灌木。",
    "care": "原产北半球温带，喜光耐旱，萌芽力强。",
    "story": "绣线菊细枝如线，白花成簇，英文名 bridal wreath 意为\"新娘花环\"，是欧洲婚礼手捧花的经典素材，象征纯洁的爱情。英国王室的婚礼花饰中常见白色小花组成的瀑布式捧花，绣线菊正是其中一员。日式庭院则把它当作\"山野草\"自然美学的代表，清新质朴。",
