    "meaning": "守护",
    "season": "春",
    "blurb": "白花如雪，秋来红果满枝。",
    "morph": "落叶小乔木，伞房花序，花白色，花药粉色。",
    "culture": "象征守护，秋日红果寓意收获。",
    "care": "原产中国，喜光耐寒，抗逆性强。",
    "story": "山楂花在欧洲民间是\"希望之花\"，五月节常以山楂枝装饰十字架；都铎王朝红白玫瑰战争的传说也与山楂有关。动画《哈尔的移动城堡》里，苏菲与哈尔初遇的小镇街道旁就有山楂树与花。现代园艺中，白色山楂花象征纯真与守护，是春日篱笆上的温柔风景。",
    "image": "images/crataegus-pinnatifida.webp",
