    "morph": "藤性灌木，花朵硕大，粉黄或白色，茶香馥郁。",
    "culture": "象征优雅，是玫瑰园中的香气担当。",
    "care": "栽培品种，喜光喜肥，冬季需防寒。",
    "story": "香水月季香气浓郁，是\"玫瑰香\"香水的重要原料。法国香水之都格拉斯的花田就大量种植这类浓香月季，电影《香水》的故事背景正是格拉斯。香水界常说的\"五月玫瑰\"其实多指千叶蔷薇，与香水月季同属浓香系。它代表馥郁、浪漫与高级感，是香水的灵魂之花。",
