    "story": "木香花白或黄，花小繁密而香浓，古称\"木香\"，是江南园林藤蔓造景的经典。明代计成《园冶》专述\"木香架\"，苏州园林里的木香棚是夏日纳凉胜景。民国散文里常见\"一架木香满院香\"的闲适意象；如今城市庭院与高架桥墩也喜植木香做花墙，花香随晚风飘远。",
