    "aliases": [
      "小茶梅"
    ],
    "meaning": "谦让",
    "season": "秋冬",
    "blurb": "山茶与梅之间的清雅之花。",
    "morph": "常绿灌木，花较小，粉红或白色，秋冬开放，叶似茶。",
    "culture": "象征谦让，是冬园一景。",
