    "story": "茶梅花形似山茶而株形更秀气，花期在秋冬，仿佛\"山茶与梅的合体\"。《花镜》称其\"花与茶花无异而实小\"。日本茶道庭院常植茶梅，冬季茶会中的茶梅是\"风物诗\"。现代园林里茶梅可作绿篱与地被，秋冬开花，象征谦逊与清雅，为萧瑟季节添一抹暖色。",
