    "care": "原产广西，喜温暖湿润半阴环境。",
    "story": "金花茶是山茶家族中唯一开金黄色的珍稀种，被誉为\"植物界的大熊猫\"。1960年在广西首次被发现，曾轰动国际植物学界，被称为\"茶族皇后\"。纪录片《秘境之眼》曾专门介绍它的野外家园。因数量稀少，金花茶被列为国家一级保护植物，象征珍稀与奇迹。",
