    "meaning": "爱的喜悦",
    "season": "春",
    "blurb": "满山红遍，热烈奔放。",
    "morph": "落叶或常绿灌木，花冠漏斗形，红粉白紫，簇生枝头。",
    "culture": "映山红，象征爱的喜悦与热烈。",
    "care": "原产东亚山地，喜酸性土，忌碱性水肥。",
    "story": "杜鹃花与杜鹃鸟同名，传说杜鹃鸟啼血染红满山花朵，李白\"蜀国曾闻子规鸟，宣城还见杜鹃花\"把这对千年搭档写进同一句诗。革命年代，\"映山红\"成了红色经典——电影《闪闪的红星》里那句\"若要盼得哟红军来，岭上开遍哟映山红\"，让漫山杜鹃成了希望与信仰的意象。|| 杜鹃是杜鹃花科的庞大家族：井冈山的映山红、贵州百里杜鹃风景区的花海、四川高山上的大树杜鹃，从平原开到海拔三千米。它还是比利时等国园艺师的心头好，西洋杜鹃便是中国杜鹃杂交培育的成果，冬季温室里开得轰轰烈烈。|| 花语为繁荣、热烈与思乡。杜鹃花开满山时，春天就有了颜色和声音。养护上杜鹃喜酸性土壤、忌暴晒与积水，春夏之交见干见湿，便能年年开成一片花云；若逢一场春雨，漫山花海更添湿润的灵气。",
    "image": "images/rhododendron-simsii.webp",
