    "story": "马缨杜鹃是高山杜鹃中的大家闺秀，花大如球、色红似火，云南马缨花山因此得名。它生于海拔两千米以上的山林，是彝族传说中的\"马缨花神\"，彝族姑娘出嫁要佩戴马缨花。纪录片《美丽中国》拍摄过云南高山马缨杜鹃盛开的花海，气势壮美，象征坚韧与炽热的生命力。",
