    "meaning": "崇高、收获",
    "season": "秋",
    "blurb": "八月桂花香，清可绝尘。",
    "morph": "常绿乔木或灌木，花小，黄白或橙红，聚伞花序，香气馥郁。",
    "culture": "象征崇高与收获，蟾宫折桂喻功名有成。",
    "care": "原产中国，喜光耐半阴，忌积水。",
    "story": "\"桂子月中落，天香云外飘\"，古人相信月中也有桂树，吴刚伐桂的传说流传千年；\"蟾宫折桂\"因此成了金榜题名的美谈，科举时代的读书人把桂花当好运的象征。桂花香极浓却不见花——米粒大的花朵藏在叶间，香气却能飘满整条街，所以又被称为\"九里香\"。|| 秋天是桂花的季节：杭州满觉陇的\"桂花雨\"闻名全国，桂花糕、桂花酿、桂花糖藕是江南餐桌的秋味；电视剧《甄嬛传》里，娘娘们桌上的桂花酿与桂花糖是宫廷生活的温柔点缀。桂与\"贵\"谐音，两桂并植寓意\"双贵\"，庭院里种桂，是中国人最朴素的愿望。|| 花语为收获、吉祥与永伴佳人。一树桂花，就是一座城市秋天的嗅觉记忆。庭院里种桂还有讲究：桂花宜在屋前，取\"门前有桂，贵气盈门\"之意，是中国人最吉利的绿化。",
