    "story": "丁香花小而香浓，诗句\"青鸟不传云外信，丁香空结雨中愁\"让它与愁绪相连，李商隐亦有\"丁香空结雨中愁\"之叹。戴望舒《雨巷》里\"一个丁香一样地结着愁怨的姑娘\"是现代文学名篇。哈尔滨以丁香为市花，丁香节成城市名片；它象征纯洁、哀愁与暗香流动的思念。",
