    "meaning": "忠贞、清纯",
    "season": "夏",
    "blurb": "一卉能熏一室香。",
    "morph": "常绿灌木，花白色，单瓣或重瓣，清香四溢。",
    "culture": "象征忠贞清纯，茉莉花歌传唱四方。",
    "care": "原产南亚，喜温暖湿润强光，忌霜冻。",
    "story": "民歌《茉莉花》是中国流传最广的旋律之一，被意大利作曲家普契尼写进歌剧《图兰朵》，成为西方人最早认识的中国音乐符号；2004年雅典奥运会闭幕式、2008年北京奥运会颁奖仪式上，它都曾响起。茉莉花茶是北方人最熟悉的茶香，福建福州是茉莉花茶的发源地，茉莉花与绿茶窨制，香气清雅持久。|| 宋代诗人赞它\"他年我若修花史，列作人间第一香\"；江南女子把茉莉花串成手串、别在衣襟，是夏夜街头最温柔的风景，老上海的白兰花摊旁总少不了茉莉。|| 花语为质朴、纯洁与忠贞。茉莉谐音\"莫离\"，寓意不离不弃，是低调却有分量的小白花。泡一杯茉莉花茶，揭开杯盖的那一刻，香气扑面而来，是许多北方家庭最熟悉的味道；茉莉花虽小，却把\"清雅\"二字做到了极致。",
    "image": "images/jasminum-sambac.webp",
