    "care": "原产中国，喜光耐寒，耐旱怕涝。",
    "story": "迎春花是春天最早的信使，\"金英翠萼带春寒\"写它凌寒而开。它与梅花、水仙、山茶并称\"雪中四友\"。老北京四合院墙角常见迎春花枝条垂落，纪录片《园林》里迎春花是北方早春第一抹金黄。它象征希望、坚韧与新年伊始的好兆头，民间也以\"迎春\"为正月花神之一。",
