    "care": "原产中国，喜光，藤粗壮需强支撑。",
    "story": "紫藤是暮春最浪漫的藤蔓。李白\"紫藤挂云木，花蔓宜阳春\"写它的飘逸；现代城市里，嘉定紫藤园、上海辰山植物园的紫藤长廊每到花期便挤满打卡的人，垂瀑般的紫色花穗随风轻晃，美得不真实。|| 动画《言叶之庭》里，新海诚用紫藤与雨景营造少年心事；《终将成为你》中，紫藤花廊见证两个少女的成长与靠近；《鬼灭之刃》里紫藤花纹被用来驱鬼，呼应它在日本文化中的\"灵力\"传说。紫藤寿命极长，日本足利花卉公园有一株一百五十多年的紫藤，花棚占地千余平方米，是\"一生要看一次\"的风景。|| 花语为沉迷的爱、执着的等待。紫藤垂落的姿态，像极了说不出口的心事。紫藤喜阳光、忌积水，种在廊架旁三五年便能成瀑；花落时节，紫色花瓣铺满地面，如一张天然花毯。",
