    "care": "原产马达加斯加，喜热带光热。",
    "story": "凤凰木红花如焰，盛放时满树如火，花期恰逢毕业季，被称为\"毕业花\"。香港、厦门、广州的街道与校园里，凤凰花落满地时恰是学生离校时，承载无数青春告别。余光中曾写诗咏凤凰木。它原产马达加斯加，如今是华南城市的夏日名片，象征热烈、离别与难忘的青春。",
