    "story": "蓝花楹紫蓝色的花雾在暮春初夏弥漫，澳大利亚悉尼、昆士兰及中国云南、福建的蓝花楹大道都是网红打卡地。它花期短暂而盛放热烈，花落后铺成紫色地毯，被称为\"紫色梦境\"。许多浪漫电影的街景都借蓝花楹营造氛围；花语为宁静、深远与在绝望中等待爱情。",
