    "story": "火焰木花朵橙红如火焰，聚生于枝顶，是非洲热带稀树草原的标志性花木，英文名非洲郁金香树。深圳、广州等地引种后成为\"行道树里的火焰\"。它花形如郁金香而色更炽烈，象征热情与生命力；原产地传说中，火焰木开花意味着旱季将尽、雨季将至，是草原的报信者。",
