    "story": "凌霄花攀援而上，花开橙红如喇叭。舒婷《致橡树》里\"我如果爱你，绝不像攀援的凌霄花，借你的高枝炫耀自己\"，让它成为独立爱情的著名意象。白居易则批评过它\"托根附树身，开花寄树梢\"。它既能上墙成瀑，也可立架成荫，象征向上攀登的勇气与执着。",
