    "care": "原产东亚，喜光耐旱，萌蘖力强。",
    "story": "木槿花开于盛夏，朝开暮落，古人以其喻\"日新\"之德，《诗经》有\"颜如舜华\"之句，舜华即木槿。韩国以木槿为国花，称\"无穷花\"，象征民族坚韧。它花期极长，整个夏天花开不断，虽每朵只有一日，却日日更新，花语为温柔的坚持与永恒的爱。",
