    "culture": "象征纯洁真挚，望春花是早春信使。",
    "care": "原产中国中部，喜光，喜肥沃深厚土壤。",
    "story": "玉兰是早春第一批开花的树，白花如盏如玉，先花后叶，满树亭亭。上海把玉兰定为市花，市标上的白玉兰家喻户晓；北京颐和园乐寿堂前的古玉兰、西安慈恩寺的玉兰花，都是春天排队打卡的风景。王维《辛夷坞》\"木末芙蓉花，山中发红萼\"咏的辛夷，正是玉兰的近亲紫玉兰。|| 玉兰入画入诗，齐白石、吴昌硕都爱画它；民间把玉兰与海棠、牡丹、桂花组合，取\"玉堂富贵\"的好彩头。它花朵大而挺立，凋谢时花瓣整朵坠落，落地依然洁白，是一种有尊严的美。|| 花语为高洁、感恩与真挚的情谊。玉兰花开，像树上落满了白鸽。春寒料峭时它率先开花，是北方最早迎接春天的花树，一树白花如云。玉兰树形挺拔，可高达十余米，适合庭院孤植或列植成行，春来一树花开，气势不输任何名花。",
