    "care": "原产中国南方，喜光耐旱。",
    "story": "木棉是广州的市花，早春先叶开花，红艳如炬，落花掷地有声，人称\"英雄树\"。舒婷《致橡树》以木棉自喻，\"我必须是你近旁的一株木棉，作为树的形象和你站在一起\"成为爱情独立宣言。羊城八景\"红棉雀跃\"即咏木棉。它象征英雄气概与并肩而立的爱情。",
    "image": "images/bombax-ceiba.webp",
