    "story": "三角梅的\"花\"其实是三片艳丽的苞片，真花藏于其中，南方人称\"叶子花\"。它是厦门市花，深圳、珠海等城市满城皆花，姹紫嫣红爬满高架与阳台。它原产南美，在热带大放异彩。它象征热情、坚韧与永不凋谢的盛放，是南国最灿烂的花墙。",
