    "story": "葱兰叶如葱、花如莲，白花六瓣，秋雨过后成片开放，又称\"风雨花\"。它雨后开花如约而至，是草坪与路边最常见的洁净小花。它象征期待与守约，花语是\"洁白的爱\"，总在风雨后带来清新的一地星白。原产中南美，白花如莲，风雨后成片开放，是\"风雨花\"之一。",
    "image": "images/zephyranthes-candida.webp",
