    "care": "原产中国，喜光耐旱，花可食用。",
    "story": "萱草古称\"谖草\"，古人以为可忘忧，故又名忘忧草。它是中国的\"母亲花\"，《诗经》\"焉得谖草，言树之背\"写种萱于北堂以解母忧。金针菜即其花蕾干制品，是餐桌上的\"黄花菜\"。它象征母爱的温暖与忘却烦恼的慰藉。",
