    "family": "百合科",
    "colors": [
      "多彩"
    ],
    "aliases": [
      "杂交萱草"
    ],
    "meaning": "快乐",
    "season": "夏",
    "blurb": "花色繁多，灿烂一夏。",
    "morph": "多年生草本，花大色艳，多彩，花期长。",
    "culture": "象征快乐，现代园艺杂交种。",
    "care": "栽培品种，喜光，耐旱耐热。",
    "story": "大花萱草是萱草的园艺改良种，花大色艳，花期从初夏绵延到初秋，是花境与路边的\"多年生劳模\"。它比野生萱草花更大、色更丰富，欧美园艺界培育出上千品种。它象征持久的陪伴与日常的幸福，是\"开不完的夏日\"。它耐寒耐旱，几乎无病虫害，是\"种下就不用人管\"的省心花。",
