    "culture": "象征宁静，林下阴生佳品。",
    "care": "原产中国，喜阴湿。",
    "story": "紫萼与玉簪同属，花紫白相间，比玉簪更耐晒耐旱，叶片宽大如扇。它是古典园林林下与墙角的常客，花形如小钟。它象征沉静与坚守，是\"玉簪的妹妹\"，花语为静谧的优雅。生于林下阴处，花紫白如小钟，耐晒耐旱，是园林树荫下的清雅花丛。",
    "image": "images/hosta-ventricosa.webp",
