    "care": "原产中国南方，喜温暖半阴。",
    "story": "建兰产自福建，一茎数花，夏秋开花，是国兰中花期最长、最易栽培的种类。它香气清冽，是闽南人家案头的常客。苏轼\"春兰如美人，不采羞自献\"咏兰诗传世。它象征清雅与寻常人家里的雅趣，是\"百姓案头的一缕幽香\"。",
