    "culture": "象征清冷，幽香独守寒窗。",
    "care": "原产中国南方，喜凉爽半阴。",
    "story": "寒兰秋冬开花，花姿清瘦，香气冷冽悠远，是兰中\"高冷美人\"。它花期在百花凋零时，与\"岁寒三友\"气质相通。寒兰产地多在福建、江西、湖南的山林，传统兰谱中属于\"奇品\"。它象征孤傲、坚韧与凌寒而开，是\"冬天里最清冷的一缕香\"。",
    "image": "images/cymbidium-kanran.webp",
