    "culture": "象征幸福飞来，年宵花之王。",
    "care": "原产东南亚，喜暖湿半阴，附生栽培。",
    "story": "蝴蝶兰花形如蝶，花色繁多，是年宵花市场的\"花中皇后\"，也是婚礼与开业最常见的送礼盆栽。它原产东南亚，台湾是重要产地。电影《霸王别姬》与许多都市剧里，蝴蝶兰常出现在精致案头。它象征幸福飞来、爱情美满。它养护需散射光与通风，浇水见干见湿，一支花箭可开两三个月。",
    "image": "images/phalaenopsis-aphrodite.webp",
