    "care": "栽培杂交种，喜凉爽昼夜温差。",
    "story": "大花蕙兰是国兰与热带兰杂交的\"混血贵族\"，花大色艳，一箭可开十余朵，是春节花市的高端年花。它花形如国兰而体量放大，既有东方的雅又有西方的艳。它象征丰盛、尊贵与吉祥，是\"兰花里的牡丹\"，新年客厅的镇场之花。",
