    "care": "原产亚洲热带，喜暖湿半阴，附生栽培。",
    "story": "石斛是兰科植物中的\"仙草\"，铁皮石斛是传统滋补药材，《本草纲目》载其益胃生津。它的花紫白相间，优雅下垂，既是药也是花。石斛枫斗是名贵中药。它象征健康、慈爱与坚韧，是\"可入药的花中君子\"。它附生栽培需透气基质，春夏花期如瀑布垂落，兼具观赏与养生。",
