    "care": "原产东亚，喜凉爽湿润半阴。",
    "story": "虾脊兰因花形似虾脊得名，唇瓣奇特，绿紫褐各色，生于山野林下。它是兰科中低调的种类，花期初夏。它象征质朴与内秀，是\"山野里的隐秘兰花\"，常在植物爱好者的小圈子里被珍视。生于山野林下，花色绿紫褐，低调内秀，是兰科中的\"山野隐士\"。",
