    "story": "球兰花球如蜡制绣球，香气甜蜜，是著名的观花藤本盆栽，垂吊于阳台格外雅致。它花蜜可滴落，故又称\"蜜糖花\"。它象征青春、圆满与甜蜜，是\"会开花的小蜡球\"，深受植物收集爱好者喜爱。原产亚洲热带，花球如蜡制绣球，垂吊盆栽，花蜜可滴落。",
