    "culture": "象征自由，天堂鸟之花。",
    "care": "原产南非，喜暖光，忌涝。",
    "story": "鹤望兰花形如仙鹤仰望，又名天堂鸟花，原产南非，是热带花艺的标志性切花，象征自由与天堂。它叶大如芭蕉，四季常绿。电影《狮子王》的非洲场景与无数热带主题设计都借它点睛。它象征幸福、自由与梦想的翱翔。它喜光耐旱，盆栽需深盆，切花水养可达两周，是花艺师的宠儿。",
    "image": "images/strelitzia-reginae.webp",
