    "care": "原产南美热带，喜暖湿半阴。",
    "story": "蝎尾蕉花序下垂如龙虾钳，红黄相间，又称\"垂花火鸟蕉\"，是热带切花市场的异域明星。它原产中南美洲，花形张扬热烈。它象征张扬的热带魅力与异域风情，是\"挂在枝头的火烈鸟\"，常出现在热带花艺设计中。它适合热带庭院与温室栽培，垂吊的花序是花艺设计里的\"异域点睛\"。",
