    "story": "红掌佛焰苞红艳如掌，肉穗花序金黄，是花店与办公桌上最常见的盆栽切花，象征热情与好运。它原产哥伦比亚热带雨林，如今全球温室广泛栽培。它花期极长，一朵能开数月。它象征大展宏图与热烈的心，是\"四季常红的幸运花\"。",
