    "morph": "多年生草本，佛焰苞白色，似白帆，四季开花。",
    "culture": "象征平静，一帆风顺。",
    "care": "原产美洲热带，喜半阴湿润。",
    "story": "白掌佛焰苞洁白如帆，又称\"一帆风顺\"，是寓意最好的办公与家居绿植之一，象征事业顺遂。它耐阴好养，水培土培皆宜，还能净化空气。它象征平静、顺利与美好的祝福，是\"白帆起航\"的幸运草。原产中南美，白帆佛焰苞，耐阴好养，是\"一帆风顺\"的幸运绿植。",
