    "story": "大花美人蕉是美人蕉的园艺改良种，花更大、色更浓，花瓣有光泽如丝绒。它常与热带花境搭配，营造度假风情。它象征热情与自信，是\"花坛里的热带女王\"，花期持久，越晒越艳。美人蕉园艺种，花大如绸，是花坛与热带花境的\"女王\"，越晒越艳。",
