    "story": "凤眼莲即水葫芦，紫色花冠带蓝黄斑点如孔雀眼，故名。它繁殖力惊人，曾是水体绿化的功臣，却也因泛滥成灾被称为\"生态杀手\"。它象征美丽与危险的平衡，是\"水面上最艳丽的入侵者\"，引人反思生态保护。生于水面，紫花带孔雀眼斑，繁殖惊人，是美丽而危险的\"入侵者\"。",
    "image": "images/eichhornia-crassipes.webp",
