    "id": "alisma-plantago-aquatica",
    "name": "泽泻花",
    "en": "Water plantain",
    "latin": "Alisma plantago-aquatica",
    "family": "泽泻科",
    "colors": [
      "白",
      "粉"
    ],
    "aliases": [
      "水白菜花"
    ],
    "meaning": "清幽",
    "season": "夏",
    "blurb": "细小白花，亭立水畔。",
    "morph": "多年生水生草本，叶卵形，花白粉，伞形花序。",
