    "care": "原产欧亚，喜水湿强光。",
    "story": "泽泻是中医利水渗湿的常用药，白花生于水泽边，故得名。它花小繁密，是湿地与药田的常见植物。它象征清润与奉献，是\"水泽边的白色星尘\"，花语为淡泊明志。生于水泽湿地，全草入药利水，白花如星，是湿地生态与药田的常客。",
