    "story": "波斯菊细枝高挑，粉白紫红花开如星，原产墨西哥，如今是高原与路边的野花明星。它秋日盛开，是\"格桑花\"最常见的指代，西藏民歌里格桑花象征幸福与吉祥。它象征自由、明朗与少女心，是\"风中的彩色格桑\"。它耐旱耐贫瘠，种子一撒便开花，是新手第一次\"播种成功\"的花。",
