    "story": "洋甘菊金黄的花心配白瓣，香气如苹果，是安神茶的主角，睡前一杯洋甘菊茶是许多人舒缓压力的仪式。它原产欧洲，古埃及人已用它敬神。它象征苦难中的力量与安宁，是\"可以喝的月光\"，治愈系香气的代表。原产欧洲，白瓣黄心香如苹果，是安神茶与护肤品的经典原料。",
