    "story": "天人菊红黄相间的花瓣如火焰与夕阳，是北美草原与海滨沙地的\"抗造花\"。它耐旱耐盐碱，花期漫长，是生态修复与路边花海的优选。它象征团结与顽强，是\"沙地上的小火炬\"，热烈而坚毅。原产北美，红黄相间如火焰，耐旱耐盐，是沙地海滨的\"小火炬\"。",
