    "story": "蓍草是《周易》占卜所用的\"筮草\"，古人以蓍草起卦，历史可追溯数千年。它白色或粉色小花成伞形，也是欧洲传统药草。它象征智慧与预见，是\"会算卦的野花\"，叶可入药止血。生于山野路旁，白粉花成伞形，是《周易》占卜之草，全草可入药。",
