    "care": "原产中国，喜凉光，忌积水，宜秋栽。",
    "story": "牡丹是中国的\"花中之王\"。刘禹锡\"唯有牡丹真国色，花开时节动京城\"，写的是唐代长安人倾城赏牡丹的盛况；欧阳修《洛阳牡丹记》是现存最早的牡丹专著，\"洛阳牡丹甲天下\"流传至今。牡丹入画，是工笔花鸟的头号主角，寓意富贵吉祥。|| 《甄嬛传》里，华妃与皇后以牡丹比宠，一句\"唯有牡丹真国色\"道尽宫廷权力；现实中的牡丹则更从容：菏泽、洛阳每年举办牡丹花会，花田如锦，游客如织。民间把牡丹与玉兰、海棠、桂花并称\"玉堂富贵\"，年画里总少不了它。|| 花语为富贵、圆满与雍容华贵。它花期虽短，盛开时却气势夺人，一朵便撑起整个春天——这就是花中之王的气场。此外，牡丹还是中国国花呼声最高的候选之一，洛阳、菏泽花会每年接待数百万游客。",
