    "culture": "象征同情，兔儿牡丹。",
    "care": "原产东亚与北美，喜半阴凉爽。",
    "story": "荷包牡丹花朵如成串的小荷包，粉红心形，故又称\"心花\"。它并非牡丹而是罂粟科植物，却以牡丹之名流传。它原产中国，欧洲花园亦爱种植。它象征浪漫与相思，是\"挂在枝头的小荷包\"，花语为永结同心。生于林下阴处，粉红心形花串，是罂粟科却以牡丹之名流传。",
