    "care": "原产地中海，喜光干燥，忌涝。",
    "story": "薰衣草是普罗旺斯的紫色名片。法国南部成片的薰衣草田让\"普罗旺斯\"这个词自带香气，电影《又见一帘幽梦》与无数婚纱照都取景于此；动画与日剧里的紫色花田，也是浪漫场景的常客。它花语\"等待爱情\"，源自普罗旺斯一个传说：少女等待远征的恋人，从春等到冬，薰衣草开了一茬又一茬。|| 薰衣草精油是芳疗的入门香，安神助眠；薰衣草香包、花茶、沐浴用品遍布生活。它耐旱喜光，地中海气候是它的故乡，新疆伊犁则是中国的\"薰衣草之乡\"，每年六月紫色花海不输法国。|| 花语为宁静、守候与期待爱情。薰衣草开的不是花，是\"慢慢等\"的浪漫。薰衣草田里常有蜜蜂嗡嗡，伊犁薰衣草蜜也是当地特产，香气随花田飘远。每年六月盛花期，伊犁还会举办薰衣草节，花田与蓝天相映，如一幅紫色的油画。",
    "image": "images/lavandula-angustifolia.webp",
