    "care": "原产东亚，喜光耐旱，根入药。",
    "story": "桔梗是朝鲜族民歌《桔梗谣》的主角，\"道拉基\"唱的是少女采桔梗的欢快场景；它蓝紫色的花朵如铃铛，花苞鼓起像个小气球，捏一下会\"啪\"地裂开，是山野里最有趣的野花。它的根是韩国泡菜与药膳的常见食材，中医也用它宣肺利咽。|| 动漫《犬夜叉》中，桔梗是与戈薇同名的重要角色——守护四魂之玉的巫女，与犬夜叉的悲剧恋情贯穿全剧，\"桔梗\"二字因此成了无数观众心口的朱砂痣。日本把桔梗列入\"秋七草\"，是俳句与和歌里的常客。|| 花语为永恒的爱、无悔与诚实。桔梗的蓝是山野里最干净的蓝，见过一次就很难忘。在韩国，桔梗根还被做成凉拌菜\"道拉基\"，是国民小菜与餐桌上的乡愁。桔梗喜光耐旱，山坡草地随处可见；秋日蓝花点缀草丛，是山野里最干净的一抹蓝。",
