    "story": "黄槐是南方常见的行道树，秋冬黄花满树，落叶时满地金黄，又称\"金凤花树\"。它是夏威夷的州花之一。它象征灿烂与温暖，是\"南方的黄金树\"，花语为热情。它花期长，落叶后稍加修剪即可整形，是南方秋冬最醒目的行道树。",
