    "story": "络石花白花五瓣旋转如风车，香气如茉莉，又称\"风车茉莉\"，是庭院藤蔓的\"香墙\"。它四季常绿，春夏开花。它象征安全与陪伴，是\"爬满墙的白风车\"，花语为万德吉祥。它耐阴耐旱，攀爬力强，适合装饰墙面与廊柱，四季常绿。",
