    "care": "原产西非，喜暖光湿润。",
    "story": "龙吐珠白色萼片托着红色花冠，花蕊如珠吐出，故名，是热带庭院与盆栽的\"仙气花\"。它原产西非，花期长。它象征珍贵与奇迹，是\"含着红珠的白龙嘴\"，花语为热情与神秘。它喜温暖湿润，冬季需移入室内，是南国庭院与阳台的特色花。",
    "image": "images/clerodendrum-thomsoniae.webp",
