    "story": "嘉兰花瓣反卷如火焰，红黄相间，是津巴布韦的国花，也是\"火焰百合\"。它生于热带，是名贵切花。它象征荣耀与热烈，是\"开成火焰的百合\"，花语为荣光。生于热带林缘，攀援生长，花瓣反卷如焰，是名贵切花，也是津巴布韦的国花。",
