    "care": "原产南美，喜暖光，忌涝。",
    "story": "朱顶红花大如喇叭，红白粉橙皆有，是春节与年宵花市的\"鸿运当头\"，寓意富贵吉祥。它原产中南美洲，鳞茎硕大。它象征渴望被爱，是\"冬天里的大红喇叭\"，花语为成双成对。它一箭可开四到六朵大花，花谢后养好球根，来年春节还会再开。",
