    "care": "原产中国，喜光耐旱。",
    "story": "醉鱼草紫色小花成串如穗，香气能引蝶，故又称\"蝴蝶灌木\"，是生态花园吸引蝴蝶蜜蜂的明星。它因茎叶醉鱼得名。它象征自由与新生，是\"蝴蝶的紫色驿站\"，花语为信仰。原产中国，紫花成穗香引蝶，是生态花园的\"蝴蝶灌木\"，秋果亦可观。",
